mapper.select:
select content_id as id, source_hash
from content_embeddings
where model_key = #{model}

select suggestion_id as id, source_hash
from suggestion_embeddings
where model_key = #{model}

select actor_key as id, source_hash
from user_interest_embeddings
where model_key = #{model}

mapper.delete:
delete from content_embeddings
where model_key = #{model}
  and content_id not in

    #{activeId}

delete from suggestion_embeddings
where model_key = #{model}
  and suggestion_id not in

    #{activeId}

delete from user_interest_embeddings
where model_key = #{model}
  and actor_key not in

    #{activeId}

mapper.select:
select ce.content_id as id,
       1 - (ce.embedding <=> query_vector.embedding) as similarity
from content_embeddings ce
join content_items c on c.id = ce.content_id
cross join (
    select cast(
        #{query,typeHandler=com.github.hgdcoder.flowershow.persistence.mapper.recommendation.FloatVectorTypeHandler}
        as vector
    ) as embedding
) query_vector
where ce.model_key = #{model}
  and ce.dimensions = #{dimensions}
  and c.status = 'published'
  and c.visibility = 'public'
  and c.type = 'video'
order by ce.embedding <=> query_vector.embedding, ce.content_id
limit #{limit}

select se.suggestion_id as id,
       1 - (se.embedding <=> ui.embedding) as similarity
from user_interest_embeddings ui
join suggestion_embeddings se
  on se.model_key = ui.model_key
 and se.dimensions = ui.dimensions
where ui.actor_key = #{actorKey}
  and ui.model_key = #{model}
  and ui.dimensions = #{dimensions}
order by se.embedding <=> ui.embedding, se.suggestion_id
limit #{limit}
